window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f1f2d9523089d24b"]={"versions": [{"id": "FIG-f1f2d9523089d24b", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2-Ebene) als UML-Klassendiagramm aus der <em>Software Component Template</em> (TPS_SWCT).</li>\n<li><strong>Architektur-Kontext:</strong> Modellierung der ECU-internen Datentransformation auf VFB-/RTE-Ebene. Das Konstrukt erweitert das <code>PortInterfaceMapping</code> (Anwendungsfall 4 nach <code>TPS_SWCT_01158</code>) zur Überbrückung formal inkompatibler Datenrepräsentationen zweier <code>PortPrototypes</code> auf derselben ECU (z. B. Transformation zwischen strukturierter Datendarstellung einer SW-C und generischem Byte-Array (<code>uint8[]</code>) für <code>NvBlockSwComponentType</code> oder <code>Dcm</code> via <code>RS_SWCT_03210</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DataPrototypeMapping</code>:</strong></li>\n<li>Repräsentiert das Mapping zwischen zwei konkreten Datenprototypen (<code>firstDataPrototype</code> und <code>secondDataPrototype</code>) innerhalb eines <code>PortInterfaceMapping</code>.</li>\n<li><strong><code>DataTransformation</code> (<code>«Identifiable»</code>):</strong></li>\n<li>Entität zur Spezifikation einer Transformationsvorschrift bzw. Transformerkette (M2-Klasse aus dem AUTOSAR Transformer Framework).</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ dataTransformationKind : DataTransformationKindEnum [0..1]</code>: Definiert den Transformationstyp (z. B. Serialisierung, E2E-Absicherung oder anwendungsspezifischer Transformer).</li>\n<li><code>+ executeDespiteDataUnavailability : Boolean</code>: Determiniert, ob der Transformer auch bei fehlenden, ungültigen oder noch nicht initialisierten Eingangsdaten aufgerufen werden muss (z. B. zur Erzeugung von Default-/Fehler-Payloads oder E2E-Statusfeldern).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Gerichtete Assoziationsrolle <code>+firstToSecondDataTransformation</code> von <code>DataPrototypeMapping</code> auf <code>DataTransformation</code>.</li>\n<li><strong>Multiplizität:</strong> <code>0..1</code> (optional; maximal eine definierte Transformationskette in Richtung vom ersten zum zweiten Datenprototyp).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Glue-Code-Generierung & Aufruf:</strong></li>\n<li>Beim Senden eines Datenelements (z. B. Aufruf von <code>Rte_Write_&lt;p&gt;_&lt;o&gt;()</code> oder <code>Rte_Send_&lt;p&gt;_&lt;o&gt;()</code>) durch die Quell-Komponente ruft die RTE synchron die konfigurierte Transformer-Funktion (<code>&lt;Transformer&gt;_Transform()</code>) auf.</li>\n<li>Das serialisierte/transformierte Datum wird anschließend im Puffer des Empfänger-Ports (<code>secondDataPrototype</code>) abgelegt bzw. per Intra-ECU-Kopieroperation bereitgestellt.</li>\n<li><strong>Bedingter Pfad (<code>executeDespiteDataUnavailability</code>):</strong></li>\n<li><code>TRUE</code>: Auch bei Dateninvalidation (<code>Rte_Invalidate()</code>) oder Pufferunterlauf wird die Transformer-Pipeline durchlaufen, um deterministische Ersatz-Frames bereitzustellen.</li>\n<li><code>FALSE</code>: Bei Datenunverfügbarkeit unterbleibt der Aufruf des Transformers; die RTE liefert unmittelbar Fehlercodes wie <code>RTE_E_NO_DATA</code> oder <code>RTE_E_INVALID</code> an den Aufrufer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (ARXML):</strong></li>\n<li>Ersetzt proprietäre Adapter-SW-Cs (Glue-Ware) durch standardisierte AUTOSAR-Transformationspipelines (<code>TPS_SWCT_01579</code>).</li>\n<li>Wird vorrangig in Systembeschreibungen eingesetzt, in denen Standard-BSW-Module (Diagnose/DCM, NvM) mit anwendungsspezifischen Schnittstellen gekoppelt werden.</li>\n<li><strong>RTE- & Performance-Auswirkungen:</strong></li>\n<li><strong>Speicher- und Laufzeit-Overhead:</strong> Die interne Transformation verlagert Marshalling/Serialisierung in den Task-Kontext der RTE. Pufferallokation (z. B. Linearisierung komplexer Records in temporäre <code>uint8</code>-Arrays) und Stack-Verbrauch steigen signifikant.</li>\n<li><strong>WCET-Analyse:</strong> Ausführungszeiten der generierten RTE-Aufrufe müssen bei Task-Schedulability- und Deadline-Betrachtungen explizit um die WCET der Transformerkette erweitert werden.</li>\n</ul>"}, {"id": "FIG-04dcdd0f9eac67d8", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2-Ebene) als UML-Klassendiagramm aus der <em>Software Component Template</em> (TPS_SWCT).</li>\n<li><strong>Architektur-Kontext:</strong> Modellierung der ECU-internen Datentransformation auf VFB-/RTE-Ebene. Das Konstrukt erweitert das <code>PortInterfaceMapping</code> (Anwendungsfall 4 nach <code>TPS_SWCT_01158</code>) zur Überbrückung formal inkompatibler Datenrepräsentationen zweier <code>PortPrototypes</code> auf derselben ECU (z. B. Transformation zwischen strukturierter Datendarstellung einer SW-C und generischem Byte-Array (<code>uint8[]</code>) für <code>NvBlockSwComponentType</code> oder <code>Dcm</code> via <code>RS_SWCT_03210</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DataPrototypeMapping</code>:</strong></li>\n<li>Repräsentiert das Mapping zwischen zwei konkreten Datenprototypen (<code>firstDataPrototype</code> und <code>secondDataPrototype</code>) innerhalb eines <code>PortInterfaceMapping</code>.</li>\n<li><strong><code>DataTransformation</code> (<code>«Identifiable»</code>):</strong></li>\n<li>Entität zur Spezifikation einer Transformationsvorschrift bzw. Transformerkette (M2-Klasse aus dem AUTOSAR Transformer Framework).</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ dataTransformationKind: DataTransformationKindEnum [0..1]</code>: Definiert den Transformationstyp (z. B. Serialisierung, E2E-Absicherung oder anwendungsspezifischer Transformer).</li>\n<li><code>+ executeDespiteDataUnavailability: Boolean</code>: Determiniert, ob der Transformer auch bei fehlenden, ungültigen oder noch nicht initialisierten Eingangsdaten aufgerufen werden muss (z. B. zur Erzeugung von Default-/Fehler-Payloads oder E2E-Statusfeldern).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Gerichtete Assoziationsrolle <code>+firstToSecondDataTransformation</code> von <code>DataPrototypeMapping</code> auf <code>DataTransformation</code> mit Multiplizität <code>0..1</code> (optional; Transformationskette vom ersten zum zweiten Datenprototyp).</li>\n<li>Gerichtete Assoziationsrolle <code>+secondToFirstDataTransformation</code> von <code>DataPrototypeMapping</code> auf <code>DataTransformation</code> mit Multiplizität <code>0..1</code> (optional; Transformationskette in Gegenrichtung vom zweiten zum ersten Datenprototyp).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Glue-Code-Generierung & Aufruf:</strong></li>\n<li>Beim Senden eines Datenelements (z. B. Aufruf von <code>Rte_Write_&lt;p&gt;_&lt;o&gt;()</code> oder <code>Rte_Send_&lt;p&gt;_&lt;o&gt;()</code>) durch die Quell-Komponente ruft die RTE synchron die konfigurierte Transformer-Funktion (<code>&lt;Transformer&gt;_Transform()</code>) auf.</li>\n<li>Das serialisierte/transformierte Datum wird anschließend im Puffer des Empfänger-Ports (<code>secondDataPrototype</code>) abgelegt bzw. per Intra-ECU-Kopieroperation bereitgestellt.</li>\n<li><strong>Bedingter Pfad (<code>executeDespiteDataUnavailability</code>):</strong></li>\n<li><code>TRUE</code>: Auch bei Dateninvalidation (<code>Rte_Invalidate()</code>) oder Pufferunterlauf wird die Transformer-Pipeline durchlaufen, um deterministische Ersatz-Frames bereitzustellen.</li>\n<li><code>FALSE</code>: Bei Datenunverfügbarkeit unterbleibt der Aufruf des Transformers; die RTE liefert unmittelbar Fehlercodes wie <code>RTE_E_NO_DATA</code> oder <code>RTE_E_INVALID</code> an den Aufrufer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (ARXML):</strong></li>\n<li>Ersetzt proprietäre Adapter-SW-Cs (Glue-Ware) durch standardisierte AUTOSAR-Transformationspipelines (<code>TPS_SWCT_01579</code>).</li>\n<li>Wird vorrangig in Systembeschreibungen eingesetzt, in denen Standard-BSW-Module (Diagnose/DCM, NvM) mit anwendungsspezifischen Schnittstellen gekoppelt werden.</li>\n<li><strong>RTE- & Performance-Auswirkungen:</strong></li>\n<li><strong>Speicher- und Laufzeit-Overhead:</strong> Die interne Transformation verlagert Marshalling/Serialisierung in den Task-Kontext der RTE. Pufferallokation (z. B. Linearisierung komplexer Records in temporäre <code>uint8</code>-Arrays) und Stack-Verbrauch steigen signifikant.</li>\n<li><strong>WCET-Analyse:</strong> Ausführungszeiten der generierten RTE-Aufrufe müssen bei Task-Schedulability- und Deadline-Betrachtungen explizit um die WCET der Transformerkette erweitert werden.</li>\n</ul>"}, {"id": "FIG-8ff1abee01b7cd0b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2-Ebene) als UML-Klassendiagramm aus der <em>Software Component Template</em> (TPS_SWCT).</li>\n<li><strong>Architektur-Kontext:</strong> Modellierung der ECU-internen Datentransformation auf VFB-/RTE-Ebene. Das Konstrukt erweitert das <code>PortInterfaceMapping</code> (Anwendungsfall 4 nach <code>TPS_SWCT_01158</code>) zur Überbrückung formal inkompatibler Datenrepräsentationen zweier <code>PortPrototypes</code> auf derselben ECU (z. B. Transformation zwischen strukturierter Datendarstellung einer SW-C und generischem Byte-Array (<code>uint8[]</code>) für <code>NvBlockSwComponentType</code> oder <code>Dcm</code> via <code>RS_SWCT_03210</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DataPrototypeMapping</code>:</strong></li>\n<li>Repräsentiert das Mapping zwischen zwei konkreten Datenprototypen (<code>firstDataPrototype</code> und <code>secondDataPrototype</code>) innerhalb eines <code>PortInterfaceMapping</code>.</li>\n<li><strong><code>DataTransformation</code> (<code>«Identifiable»</code>):</strong></li>\n<li>Entität zur Spezifikation einer Transformationsvorschrift bzw. Transformerkette (M2-Klasse aus dem AUTOSAR Transformer Framework).</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ dataTransformationKind: DataTransformationKindEnum [0..1]</code>: Definiert den Transformationstyp (z. B. Serialisierung, E2E-Absicherung oder anwendungsspezifischer Transformer).</li>\n<li><code>+ executeDespiteDataUnavailability: Boolean [0..1]</code>: Determiniert optional, ob der Transformer auch bei fehlenden, ungültigen oder noch nicht initialisierten Eingangsdaten aufgerufen werden muss (z. B. zur Erzeugung von Default-/Fehler-Payloads oder E2E-Statusfeldern).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Gerichtete Assoziationsrolle <code>+firstToSecondDataTransformation</code> von <code>DataPrototypeMapping</code> auf <code>DataTransformation</code> mit Multiplizität <code>0..1</code> (optional; Transformationskette vom ersten zum zweiten Datenprototyp).</li>\n<li>Gerichtete Assoziationsrolle <code>+secondToFirstDataTransformation</code> von <code>DataPrototypeMapping</code> auf <code>DataTransformation</code> mit Multiplizität <code>0..1</code> (optional; Transformationskette in Gegenrichtung vom zweiten zum ersten Datenprototyp).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Glue-Code-Generierung & Aufruf:</strong></li>\n<li>Beim Senden eines Datenelements (z. B. Aufruf von <code>Rte_Write_&lt;p&gt;_&lt;o&gt;()</code> oder <code>Rte_Send_&lt;p&gt;_&lt;o&gt;()</code>) durch die Quell-Komponente ruft die RTE synchron die konfigurierte Transformer-Funktion (<code>&lt;Transformer&gt;_Transform()</code>) auf.</li>\n<li>Das serialisierte/transformierte Datum wird anschließend im Puffer des Empfänger-Ports (<code>secondDataPrototype</code>) abgelegt bzw. per Intra-ECU-Kopieroperation bereitgestellt.</li>\n<li><strong>Bedingter Pfad (<code>executeDespiteDataUnavailability</code>):</strong></li>\n<li><code>TRUE</code>: Auch bei Dateninvalidation (<code>Rte_Invalidate()</code>) oder Pufferunterlauf wird die Transformer-Pipeline durchlaufen, um deterministische Ersatz-Frames bereitzustellen.</li>\n<li><code>FALSE</code>: Bei Datenunverfügbarkeit unterbleibt der Aufruf des Transformers; die RTE liefert unmittelbar Fehlercodes wie <code>RTE_E_NO_DATA</code> oder <code>RTE_E_INVALID</code> an den Aufrufer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (ARXML):</strong></li>\n<li>Ersetzt proprietäre Adapter-SW-Cs (Glue-Ware) durch standardisierte AUTOSAR-Transformationspipelines (<code>TPS_SWCT_01579</code>).</li>\n<li>Wird vorrangig in Systembeschreibungen eingesetzt, in denen Standard-BSW-Module (Diagnose/DCM, NvM) mit anwendungsspezifischen Schnittstellen gekoppelt werden.</li>\n<li><strong>RTE- & Performance-Auswirkungen:</strong></li>\n<li><strong>Speicher- und Laufzeit-Overhead:</strong> Die interne Transformation verlagert Marshalling/Serialisierung in den Task-Kontext der RTE. Pufferallokation (z. B. Linearisierung komplexer Records in temporäre <code>uint8</code>-Arrays) und Stack-Verbrauch steigen signifikant.</li>\n<li><strong>WCET-Analyse:</strong> Ausführungszeiten der generierten RTE-Aufrufe müssen bei Task-Schedulability- und Deadline-Betrachtungen explizit um die WCET der Transformerkette erweitert werden.</li>\n</ul>"}, {"id": "FIG-b2ab6fa360f33ad7", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2-Ebene) als UML-Klassendiagramm aus der <em>Software Component Template</em> (TPS_SWCT).</li>\n<li><strong>Architektur-Kontext:</strong> Modellierung der ECU-internen Datentransformation auf VFB-/RTE-Ebene. Das Konstrukt erweitert das <code>PortInterfaceMapping</code> (Anwendungsfall 4 nach <code>TPS_SWCT_01158</code>) zur Überbrückung formal inkompatibler Datenrepräsentationen zweier <code>PortPrototypes</code> auf derselben ECU (z. B. Transformation zwischen strukturierter Datendarstellung einer SW-C und generischem Byte-Array (<code>uint8[]</code>) für <code>NvBlockSwComponentType</code> oder <code>Dcm</code> via <code>RS_SWCT_03210</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>DataPrototypeMapping</code>:</strong></li>\n<li>Repräsentiert das Mapping zwischen zwei konkreten Datenprototypen (<code>firstDataPrototype</code> und <code>secondDataPrototype</code>) innerhalb eines <code>PortInterfaceMapping</code>.</li>\n<li><strong><code>DataTransformation</code> (<code>«Identifiable»</code>):</strong></li>\n<li>Entität zur Spezifikation einer Transformationsvorschrift bzw. Transformerkette (M2-Klasse aus dem AUTOSAR Transformer Framework).</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ dataTransformationKind: DataTransformationKindEnum [0..1]</code>: Definiert den Transformationstyp (z. B. Serialisierung, E2E-Absicherung oder anwendungsspezifischer Transformer).</li>\n<li><code>+ executeDespiteDataUnavailability: Boolean [0..1]</code>: Determiniert optional, ob der Transformer auch bei fehlenden, ungültigen oder noch nicht initialisierten Eingangsdaten aufgerufen werden muss (z. B. zur Erzeugung von Default-/Fehler-Payloads oder E2E-Statusfeldern).</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Gerichtete Assoziationsrolle <code>+firstToSecondDataTransformation</code> von <code>DataPrototypeMapping</code> auf <code>DataTransformation</code> mit Multiplizität <code>0..1</code> (optional; Transformationskette vom ersten zum zweiten Datenprototyp).</li>\n<li>Gerichtete Assoziationsrolle <code>+secondToFirstDataTransformation</code> von <code>DataPrototypeMapping</code> auf <code>DataTransformation</code> mit Multiplizität <code>0..1</code> (optional; Transformationskette in Gegenrichtung vom zweiten zum ersten Datenprototyp).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>RTE-Glue-Code-Generierung & Aufruf:</strong></li>\n<li>Beim Senden eines Datenelements (z. B. Aufruf von <code>Rte_Write_&lt;p&gt;_&lt;o&gt;()</code> oder <code>Rte_Send_&lt;p&gt;_&lt;o&gt;()</code>) durch die Quell-Komponente ruft die RTE synchron die konfigurierte Transformer-Funktion (<code>&lt;Transformer&gt;_Transform()</code>) auf.</li>\n<li>Das serialisierte/transformierte Datum wird anschließend im Puffer des Empfänger-Ports (<code>secondDataPrototype</code>) abgelegt bzw. per Intra-ECU-Kopieroperation bereitgestellt.</li>\n<li><strong>Bedingter Pfad (<code>executeDespiteDataUnavailability</code>):</strong></li>\n<li><code>TRUE</code>: Auch bei Dateninvalidation (<code>Rte_Invalidate()</code>) oder Pufferunterlauf wird die Transformer-Pipeline durchlaufen, um deterministische Ersatz-Frames bereitzustellen.</li>\n<li><code>FALSE</code>: Bei Datenunverfügbarkeit unterbleibt der Aufruf des Transformers; die RTE liefert unmittelbar Fehlercodes wie <code>RTE_E_NO_DATA</code> oder <code>RTE_E_INVALID</code> an den Aufrufer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (ARXML):</strong></li>\n<li>Ersetzt proprietäre Adapter-SW-Cs (Glue-Ware) durch standardisierte AUTOSAR-Transformationspipelines (<code>TPS_SWCT_01579</code>).</li>\n<li>Wird vorrangig in Systembeschreibungen eingesetzt, in denen Standard-BSW-Module (Diagnose/DCM, NvM) mit anwendungsspezifischen Schnittstellen gekoppelt werden.</li>\n<li><strong>RTE- & Performance-Auswirkungen:</strong></li>\n<li><strong>Speicher- und Laufzeit-Overhead:</strong> Die interne Transformation verlagert Marshalling/Serialisierung in den Task-Kontext der RTE. Pufferallokation (z. B. Linearisierung komplexer Records in temporäre <code>uint8</code>-Arrays) und Stack-Verbrauch steigen signifikant.</li>\n<li><strong>WCET-Analyse:</strong> Ausführungszeiten der generierten RTE-Aufrufe müssen bei Task-Schedulability- und Deadline-Betrachtungen explizit um die WCET der Transformerkette erweitert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-f1f2d9523089d24b", "to": "FIG-04dcdd0f9eac67d8", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Assoziation: Hinzufügen der gerichteten Assoziationsrolle <code>+secondToFirstDataTransformation</code> von <code>DataPrototypeMapping</code> zu <code>DataTransformation</code> mit Multiplizität <code>0..1</code>.</li>\n</ul>"}, {"from": "FIG-04dcdd0f9eac67d8", "to": "FIG-8ff1abee01b7cd0b", "fr": "R20-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Multiplizität: Attribut <code>executeDespiteDataUnavailability</code> in <code>DataTransformation</code> von <code>Boolean</code> (implizit <code>1</code>) auf <code>Boolean [0..1]</code> geändert.</li>\n</ul>"}, {"from": "FIG-8ff1abee01b7cd0b", "to": "FIG-b2ab6fa360f33ad7", "fr": "R23-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
